List<Integer> key = new ArrayList<>(List.of(1, 2));
Map<List<Integer>, String> m = new HashMap<>();
m.put(key, "v");
key.add(3);                                    // 修改参与 hashCode 的内容
m.get(key); m.containsKey(key); m.get(List.of(1, 2));

